/* prog19_palindrome_checker – reproduced behaviour
 *
 * The program accepts at most one command‑line argument.
 *   * If the argument length > 1024 → prints "TOO_LONG".
 *   * Otherwise it normalises the argument (lower‑case letters + digits,
 *     discarding everything else) and checks whether the normalised string
 *     is a palindrome.
 *   * Prints "PALINDROME" or "NOT_PALINDROME" accordingly.
 *
 * No other input (stdin) is used.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[])
{
    const char *input = "";
    if (argc > 1) {
        input = argv[1];
    }

    /* 1. Length check on the original argument */
    size_t orig_len = strlen(input);
    if (orig_len > 1024) {
        puts("TOO_LONG");
        return 0;
    }

    /* 2. Normalise: keep digits, convert letters to lower case, drop the rest */
    char norm[1025];               /* at most orig_len characters, plus NUL */
    size_t n = 0;
    for (size_t i = 0; i < orig_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalpha(c)) {
            norm[n++] = (char)tolower(c);
        } else if (isdigit(c)) {
            norm[n++] = (char)c;
        }
        /* all other characters are ignored */
    }
    norm[n] = '\0';

    /* 3. Palindrome test on the normalised string */
    int is_pal = 1;
    for (size_t i = 0, j = n ? n - 1 : 0; i < j; ++i, --j) {
        if (norm[i] != norm[j]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
